import { Effect, Option } from "effect"

export interface DeliveryPreferences {
  readonly recipientId: string
  readonly email: Option.Option<string>
  readonly locale: Option.Option<string>
}

export interface PreferenceRow {
  readonly recipientId: string
  readonly email: string | null
  readonly locale: string | null
}

export const decodePreferences = (row: PreferenceRow): DeliveryPreferences => ({
  recipientId: row.recipientId,
  email: Option.fromNullable(row.email),
  locale: Option.fromNullable(row.locale)
})

export const prepareDelivery = (row: PreferenceRow) =>
  Effect.sync(() => {
    const preferences = decodePreferences(row)
    const locale = Option.getOrElse(preferences.locale, () => "en-US")
    const email = Option.getOrElse(preferences.email, () => "unavailable")

    return {
      recipientId: preferences.recipientId,
      locale,
      email
    }
  })
